#include "spell_geometry41.h"
static void spell_world_begin41(void){gpu_depth_state(0);program(0);bindTexture(skinTexture,512,SKIN_H,2048,0x0001122a);uint32_t*p=pb_begin();for(int i=0;i<16;i++)p=pb_push1(p,NV097_SET_VERTEX_DATA_ARRAY_FORMAT+i*4,2);p=pb_push1(p,NV097_SET_CULL_FACE_ENABLE,0);p=pb_push1(p,NV097_SET_DEPTH_TEST_ENABLE,1);p=pb_push1(p,NV097_SET_DEPTH_MASK,0);p=pb_push1(p,NV097_SET_ALPHA_TEST_ENABLE,0);p=pb_push1(p,NV097_SET_BLEND_ENABLE,1);p=pb_push1(p,NV097_SET_BLEND_FUNC_SFACTOR,0x302);p=pb_push1(p,NV097_SET_BLEND_FUNC_DFACTOR,0x303);pb_end(p);}
static void spell_world_quad41(const float*m,const SpellPoint41*q,unsigned color){float u=0,v=0;unsigned i;for(i=0;i<sizeof(skinColors)/sizeof(skinColors[0]);i++)if(skinColors[i]==color){hud_solid_uv(i,&u,&v);break;}if(i==sizeof(skinColors)/sizeof(skinColors[0]))fail("Spell geometry palette missing");uint32_t*p=pb_begin();p=pb_push1(p,NV097_SET_BEGIN_END,8);for(int i=0;i<4;i++){float sx,sy;world_project(m,q[i].x,q[i].y,q[i].z,&sx,&sy);float depth=m[8]*q[i].x+m[9]*q[i].y+m[10]*q[i].z+m[11]-WORLD_SPRITE_BIAS*2;p=vertex(p,sx,sy,depth,u,v);}p=pb_push1(p,NV097_SET_BEGIN_END,0);pb_end(p);}
static void spell_aim_ring41(const Combat*g,const float*m,float x,float y,float radius,int valid){spell_world_begin41();for(int i=0;i<64;i++){float a=i*6.2831853f/64,b=(i+1)*6.2831853f/64,ax=x+cosf(a)*radius,ay=y+sinf(a)*radius,bx=x+cosf(b)*radius,by=y+sinf(b)*radius;if(fabsf(height_at(ax,ay)-height_at(x,y))>12||fabsf(height_at(bx,by)-height_at(x,y))>12||fabsf(height_at(ax,ay)-height_at(bx,by))>8)continue;if(x-radius-1<1||y-radius-1<1||x+radius+1>=gw*8-1||y+radius+1>=gh*8-1)continue;float z=height_at(x,y)+.13f;int shimmer=(int)((sinf(g->time*2.5f+a*3)+1)*1.4f);if(shimmer>2)shimmer=2;static const unsigned faint[3]={0x1965eafa,0x2165eafa,0x2965eafa};static const unsigned blues[3]={0x4065dffa,0x6065dffa,0x8065dffa};SpellPoint41 fill[4]={{x,y,z},{ax,ay,height_at(ax,ay)+.13f},{bx,by,height_at(bx,by)+.13f},{x,y,z}};spell_world_quad41(m,fill,valid?faint[shimmer]:0x0cff4848);for(int side=0;side<2;side++){float base=radius+(side?.9f:-.9f),xa=x+cosf(a)*base,ya=y+sinf(a)*base,xb=x+cosf(b)*base,yb=y+sinf(b)*base;if(fabsf(height_at(xa,ya)-height_at(x,y))>12||fabsf(height_at(xb,yb)-height_at(x,y))>12)continue;SpellPoint41 face[4]={{xa,ya,height_at(xa,ya)+.13f},{xb,yb,height_at(xb,yb)+.13f},{bx,by,height_at(bx,by)+2.13f},{ax,ay,height_at(ax,ay)+2.13f}};spell_world_quad41(m,face,valid?blues[shimmer]:0x90ff4848);}}}
static void spell_success_circle41(const Combat*g,const float*m,float x,float y,float elapsed){if(elapsed<0||elapsed>=2.1f||x<30||y<30||x>=gw*8-30||y>=gh*8-30)return;float radius=spell_circle_radius43(elapsed,48),angle=elapsed*2.4881414f,z=height_at(x,y)+.2f;int white=((int)(elapsed*4.8f)&1)==0;unsigned color=white?0xffffffff:0xffff4848;spell_world_begin41();for(int i=0;i<38;i++){float a,b;if(i<32){a=angle+i*6.2831853f/32;b=angle+(i+1)*6.2831853f/32;}else{int j=i-32;a=angle+j*6.2831853f/6;b=angle+(j+2)*6.2831853f/6;}SpellPoint41 q[4];spell_line_quad41(x+cosf(a)*radius,y+sinf(a)*radius,x+cosf(b)*radius,y+sinf(b)*radius,z,3.96f,q);spell_world_quad41(m,q,color);}}
static void quagmire_ground45(const Combat*g,const float*m){for(int n=0;n<COMBAT_FIELDS;n++){const CombatField*f=&g->fields[n];if(f->secondId!=82||!f->remaining)continue;spell_world_begin41();for(int i=0;i<48;i++){float a=i*6.2831853f/48,b=(i+1)*6.2831853f/48,ax=f->x+cosf(a)*f->radius,ay=f->y+sinf(a)*f->radius,bx=f->x+cosf(b)*f->radius,by=f->y+sinf(b)*f->radius;if(ax<1||ay<1||bx<1||by<1||ax>=gw*8-1||bx>=gw*8-1||ay>=gh*8-1||by>=gh*8-1)continue;SpellPoint41 q[4]={{f->x,f->y,height_at(f->x,f->y)+.11f},{ax,ay,height_at(ax,ay)+.11f},{bx,by,height_at(bx,by)+.11f},{f->x,f->y,height_at(f->x,f->y)+.11f}};spell_world_quad41(m,q,0x506f582fu);}}}
